challenge.solution:
lunes = "12"
martes = "34"
miercoles = "56"
jueves = "78"
viernes = "90"

dia = input("Dia de la semana: ").lower().strip()
digito = input("Ultimo digito de la placa: ").strip()
hora = int(input("Hora (0 a 23): "))
valido = True
restringidos = ""

if not (digito.isdigit() and len(digito) == 1):
    print("El digito debe ser un solo numero del 0 al 9")
    valido = False
elif hora < 0 or hora > 23:
    print("La hora debe estar entre 0 y 23")
    valido = False
elif dia == "lunes":
    restringidos = lunes
elif dia == "martes":
    restringidos = martes
elif dia == "miercoles":
    restringidos = miercoles
elif dia == "jueves":
    restringidos = jueves
elif dia == "viernes":
    restringidos = viernes
elif dia == "sabado" or dia == "domingo":
    restringidos = ""
else:
    print(f"No conozco el dia '{dia}'")
    valido = False

if valido:
    # Franjas inventadas: 6 a 8 y 17 a 19
    en_horario = (hora >= 6 and hora <= 8) or (hora >= 17 and hora <= 19)
    dia_restringido = digito in restringidos
    if dia_restringido and en_horario:
        print("Tiene restriccion")
    elif dia_restringido:
        print("Puede circular (fuera del horario)")
    else:
        print("Puede circular")

