challenge.solution:
def calcular_iva(precio, tasa=0.19):
    return precio * tasa

def total_factura(precio, descuento=0, tasa=0.19):
    # Primero el descuento sobre el precio
    rebajado = precio * (1 - descuento)
    # Luego el IVA sobre el precio ya rebajado
    return rebajado + calcular_iva(rebajado, tasa)

print(total_factura(100000))
print(total_factura(100000, 0.1))
print(total_factura(100000, tasa=0.05))

