def clasificar(nota):
    if nota >= 3.0:
        return "Aprobado"
    elif nota >= 2.5:
        return "Casi"
    return "Reprobado"

def promedio(n1, n2, n3):
    return round((n1 + n2 + n3) / 3, 1)

def reporte(nombre, n1, n2, n3):
    # Variables locales: solo existen aquí
    prom = promedio(n1, n2, n3)
    texto = clasificar(prom)
    return f"{nombre}: promedio {prom} -> {texto}"

def main():
    print(reporte("Ana", 4.0, 3.5, 3.6))
    print(reporte("Luis", 2.0, 2.5, 3.0))

main()

