import random

def elegir_numero():
    return random.randint(1, 100)

def pedir_intento():
    return int(input("Tu número: "))

def pista(intento, secreto):
    if intento < secreto:
        return "Más alto"
    elif intento > secreto:
        return "Más bajo"
    return "Correcto"

def main():
    secreto = elegir_numero()
    intentos = 0
    acierto = False
    while not acierto and intentos < 7:
        intento = pedir_intento()
        intentos += 1
        resultado = pista(intento, secreto)
        print(resultado)
        if resultado == "Correcto":
            acierto = True
    if acierto:
        print(f"Adivinaste en {intentos} intentos")
    else:
        print(f"Se acabaron los intentos. El número era {secreto}")

main()

