import sqlite3


def crear_tablas(con):
    con.execute("DROP TABLE IF EXISTS gastos")
    con.execute("CREATE TABLE gastos (fecha TEXT, categoria TEXT, valor INTEGER)")


def fila_valida(fila):
    """Devuelve la fila con el valor entero, o None si no sirve."""
    fecha, categoria, valor = fila
    try:
        valor = int(valor)
    except ValueError:
        return None          # vacío o con letras
    if valor <= 0:
        return None          # negativo o cero
    return (fecha, categoria, valor)


def cargar(con, filas):
    """Inserta las filas válidas y devuelve (insertadas, descartadas)."""
    buenas = []
    descartadas = 0
    for fila in filas:
        limpia = fila_valida(fila)
        if limpia is None:
            descartadas += 1
        else:
            buenas.append(limpia)
    with con:
        con.executemany("INSERT INTO gastos VALUES (?, ?, ?)", buenas)
    return len(buenas), descartadas


def main():
    con = sqlite3.connect(":memory:")
    # Como llegan de un CSV: todo es texto
    crudas = [("2026-12-01", "comida", "18000"), ("2026-12-02", "bus", ""),
              ("2026-12-03", "comida", "9500"), ("2026-12-04", "ocio", "abc"),
              ("2026-12-05", "ocio", "-500")]
    crear_tablas(con)
    insertadas, descartadas = cargar(con, crudas)
    print(f"Cargadas {insertadas} filas, descartadas {descartadas}")
    print(con.execute("SELECT SUM(valor) FROM gastos").fetchone()[0])


if __name__ == "__main__":
    main()

