TOPE_MENSUAL = 100000


# Versión original, solo para comparar
def f(l):
    c = 0
    e = 0
    for x in l:
        if x > 100000:
            c = c + 1
            e = e + (x - 100000)
    return c, e


def resumen_sobre_tope(totales_mensuales):
    """Devuelve (meses que superan el tope, suma de lo que se pasaron)."""
    excesos = [total - TOPE_MENSUAL for total in totales_mensuales if total > TOPE_MENSUAL]
    return len(excesos), sum(excesos)


def mostrar_resumen(meses, exceso_total):
    """Imprime el resumen en dos líneas."""
    print("Meses sobre el tope:", meses)
    print(f"Exceso total: {exceso_total:,}")


def main():
    totales_mensuales = [90000, 120000, 150000]
    # La versión limpia debe dar lo mismo que la original
    assert resumen_sobre_tope(totales_mensuales) == f(totales_mensuales)
    meses, exceso_total = resumen_sobre_tope(totales_mensuales)
    mostrar_resumen(meses, exceso_total)


if __name__ == "__main__":
    main()

